Tool response:
Tool: generate_revenue_report
Description: Generate Revenue Report
Parameters:
    {
      "type": "object",
      "properties": {
        "reporting_period_start": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Start date for the reporting period in YYYY-MM-DD format. If not provided, defaults to the first day of the previous month.",
          "title": "Reporting Period Start"
        },
        "reporting_period_end": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "End date for the reporting period in YYYY-MM-DD format. If not provided, defaults to the last day of the previous month.",
          "title": "Reporting Period End"
        }
      },
      "required": []
    }

